INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033222', 'La Venganza Del Charro Negro', 'la-venganza-del-charro-negro', 'A', 'ANIMACIÓN', 85, 'Después de varios años, el temible Charro Negro regresa con un nuevo propósito: vengarse de Leo San Juan y cobrar una deuda que ha quedado pendiente. Para lograrlo, liberará a algunas de las criaturas y leyendas sobrenaturales que Leo ha enfrentado a lo largo de sus aventuras, obligándolo a reencontrarse con sus antiguos enemigos. Pero esta vez, el Charro Negro tiene un objetivo mucho más personal: su hermano, Nando. Mientras las leyendas se desatan y el peligro crece, Leo deberá proteger a su hermano y reunir nuevamente a sus amigos para descubrir el verdadero plan del Charro Negro. En una aventura que llevará al grupo al límite, Leo tendrá que enfrentarse una vez más a las criaturas de su pasado y descubrir que, para derrotar al Charro Negro, no solo tendrá que demostrar su valentía, sino luchar por aquello que más quiere.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaVenganzaDelCharroNegro/Es/720x1022_copia_5.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaVenganzaDelCharroNegro/Es/1440x900_69.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaVenganzaDelCharroNegro/Es/6aa88358db4b3-la-vengaza-del-charro-negro.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033355', 'El Bosque Salvaje: Wildwood', 'el-bosque-salvaje-wildwood', 'B', 'ANIMACIÓN', 132, 'Después de que su pequeño hermano es secuestrado por una parvada de cuervos, la audaz adolescente, Prue, inicia una desesperada misión de rescate hacia el Bosque Salvaje acompañada únicamente por su torpe pero leal compañero de clase, Curtis. Prue navega por un mundo de animales parlantes, bandidos y poderosas figuras impulsadas por el duelo y la ambición. Mientras los amigos se ven arrastrados a un conflicto que amenaza el equilibrio del bosque mismo, Prue debe descubrir la fuerza y la fe que nunca supo que poseía. Si quiere salvar a su hermano y proteger el frágil futuro de Wildwood, tendrá que arriesgarlo todo.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElBosqueSalvajeWildwood/Es/Wildwood_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElBosqueSalvajeWildwood/Es/Header_movie_details_1440x900__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElBosqueSalvajeWildwood/Es/6ab4000547426-wildwood.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033740', 'Campeón Gabacho', 'campeon-gabacho', 'B15', 'ACCIÓN', 108, 'Liborio llega a Estados Unidos con los bolsillos vacíos y las ganas de comerse al mundo. Buscando cómo salir adelante, termina en un ring de boxeo, donde descubre que su talento para aguantar golpes puede cambiarle la vida. Entre peleas, enredos y un amor que le mueve el piso, este mexicano se abrirá camino con ingenio y mucho corazón, dispuesto a demostrar que puede llegar lejos, aunque nadie crea en él.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/CampeonGabacho/Es/CG_DESKTOP_P_ster_720x1022px_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/CampeonGabacho/Es/CG_DESKTOP_Header_flujo_de_compra_1440x900px_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/CampeonGabacho/Es/6acff69b5e51b-campeon-gabacho.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033788', 'Entrega Al Límite', 'entrega-al-limite', 'B15', 'COMEDIA, ACCIÓN', 99, 'El mensajero Frank transporta un órgano a un joven receptor que puede salvarle la vida. La misión se vuelve peligrosa cuando un despiadado jefe del crimen busca la posesión del órgano a cualquier precio.​', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/EntregaAlLimite/Es/Poster_720x1022_S_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/EntregaAlLimite/Es/Header_Movie_Details_1440x900_S_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/EntregaAlLimite/Es/6ac57f4a99209-entrega-limite.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033521', 'Clayface', 'clayface', 'C', 'TERROR, THRILLER', 108, 'De DC Studios, “Clayface” es un thriller de terror dirigido por James Watkins, protagonizado por Tom Rhys Harries en el papel principal del icónico villano favorito de culto de la galería de villanos de Gotham. El meteórico ascenso de Matt Hagen, de joven de las calles de Gotham a estrella de Hollywood, se ve trágicamente truncado cuando las acciones de un jefe del crimen local lo dejan horriblemente desfigurado. Abandonado por quienes lo rodean y sin nada que perder, Matt recurre a un tratamiento de vanguardia que milagrosamente le devuelve su apariencia anterior... pero que también altera de forma inesperada su percepción de la realidad, precipitándolo por un camino destructivo de venganza desmedida.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Clayface/Es/P_720X1022_5.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Clayface/Es/HMD_1440X900_7.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Clayface/Es/6abd9302c9bb2-clayface.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033791', 'Blue Lock', 'blue-lock', 'A', 'DRAMA, SUSPENSO, ACCIÓN', 127, '300 jugadores de fútbol compiten en despiadadas pruebas en un centro de entrenamiento secreto, donde solo uno se convertirá en el mejor delantero del mundo y los eliminados son expulsados de la selección nacional de Japón.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/BlueLock/Es/Poster_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/BlueLock/Es/Header_movie_details_1440x900px__8.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/BlueLock/Es/6acfe11089a2a-blue-lock.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033155', 'Sensatez Y Sentimiento', 'sensatez-y-sentimiento', 'A', 'ROMANCE, DRAMA', 132, 'Basada en la novela de Jane Austen, Sentido y sensibilidad es la historia de las hermanas Elinor y Marianne Dashwood y su viaje para encontrar el amor y superar el desamor y la pobreza con gracia y madurez.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/SensatezYSentimiento/Es/720x1022_copia_2__7.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/SensatezYSentimiento/Es/15_Header_Movie_details_1440x900px__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/SensatezYSentimiento/Es/6aa1c2d660ad1-sensatez-sentimiento.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033684', 'El Desconocido Del Gran Arco', 'el-desconocido-del-gran-arco', 'B', 'DRAMA', 104, 'En 1983, el presidente François Mitterrand convocó el mayor concurso de arquitectura de la historia. Su objetivo: erigir un nuevo monumento en París que al mismo tiempo se convierta en la insignia de su mandato. Para sorpresa de todos, el ganador es un absoluto desconocido: Johan Otto von Spreckelsen, un profesor de arquitectura de Copenhague quien, sin esperarlo, se convirtió en el centro de todas las miradas al quedar a cargo de la obra más ambiciosa del momento: el Arco de la Defensa de París. El filme parte de la psicología del protagonista y las adversidades que enfrenta en su proyecto para hablar de temas complejos como el enfrentamiento entre idealismo y poder político, la ética profesional y las barreras que el poder impone a la creación artística.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElDesconocidoDelGranArco/Es/720x1022_25.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElDesconocidoDelGranArco/Es/Header_Movie_details_1440x900_5.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElDesconocidoDelGranArco/Es/6ac7bbe62e85a-desconocido-gran-arco.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033826', 'Everest: La Otra Cara', 'everest-la-otra-cara', 'A', 'DOCUMENTAL, DEPORTE', 115, 'Los esquiadores de alta montaña de élite Jim Morrison e Hilaree Nelson se enamoraron profundamente mientras alcanzaban la cima de su deporte. Su determinación se convirtió en un sueño compartido: escalar y esquiar por la cara norte directa del Everest, el camino más difícil y peligroso de la montaña y la ruta de esquí más codiciada del mundo. Miles de personas han coronado la montaña por la cresta sureste de Nepal, pero solo un puñado ha llegado a la cima por esta ruta y nadie ha conseguido descender esquiando con éxito. Ya conocidos por sus extraordinarias hazañas en la montaña y acostumbrados a las pérdidas, Morrison y Nelson lo apuestan todo a este desalentador reto.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/EverestLaOtraCara/Es/19_Poster_720x1022px__5.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/EverestLaOtraCara/Es/14_Header_Movie_details_1440x900px__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/EverestLaOtraCara/Es/6ad1038729a8c-everest-otra-cara.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033681', 'The Irregular at Magic High School La Película - Arco de la Sucesión de los Yotsuba', 'the-irregular-magic-high-school-la-pelicula', 'A', 'FANTASÍA, CIENCIA FICCIÓN, ANIME', 104, 'En un mundo de tecnología mágica, los hermanos Tatsuya y Miyuki son invitados a un banquete de Año Nuevo en el que se elegirá al próximo líder del poderoso clan Yotsuba. Para Miyuki, convertirse en líder significaría elevar el estatus humilde de su hermano, pero a costa de la vida que comparten. Secretos y conspiraciones salen a la luz mientras los hermanos toman una decisión que lo cambiará todo.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/TheIrregularatMagicHighSchoolLaPeliculaArcodelaSucesiondelosYotsuba/Es/IrregularAtMagicHighSchool_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/TheIrregularatMagicHighSchoolLaPeliculaArcodelaSucesiondelosYotsuba/Es/IrregularAtMagicHighSchool_1440x900_copia_2_.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/TheIrregularatMagicHighSchoolLaPeliculaArcodelaSucesiondelosYotsuba/Es/6ac7bb842a2aa-the-irregular-at-magic.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033317', 'HCF: HYBE CHEERING PARTY ', 'hcf-hybe-cheering-party', 'A', 'CONCIERTO', 60, '¡El entusiasmo por los artistas de HYBE llega a los cines! ¡Canta con tus artistas favoritos de HYBE en 3D! Se acerca una proyección única, tipo juego, en la que los fans podrán corear consignas y agitar sus barras luminosas mientras ven los videos musicales de BTS, SEVENTEEN, TOMORROW X TOGETHER, ENHYPEN, LE SSERAFIM, &TEAM, BOYNEXTDOOR, TWS, ILLIT, KATSEYE, aoen, CORTIS y SANTOS BRAVOS en pantalla grande. ¡Únete a esta celebración inolvidable llena de música variada, la energía apasionada de los fans y una deslumbrante ola de Light Sticks!', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/HCFHYBECHEERINGPARTY/Es/Poster_WEB_Desktop_720x1022px_38__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/HCFHYBECHEERINGPARTY/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_38__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/HCFHYBECHEERINGPARTY/Es/6ac6a58445109-hybe-fest.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033246', 'Rammstein - Live in Mexico City', 'rammstein-live-in-mexico-city', 'B15', 'EN VIVO', 110, 'Rammstein - Live in Mexico City', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/RammsteinLiveinMexicoCity/Es/Poster_WEB_Desktop_720x1022px_38__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/RammsteinLiveinMexicoCity/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_38__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/RammsteinLiveinMexicoCity/Es/6ac6a6a81fbf4-rammstein.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ozzy-black-sabbath-back-to-the-beginning', 'Ozzy & Black Sabbath: Back To The Beginning', 'ozzy-black-sabbath-back-to-the-beginning', 'A', 'DOCUMENTAL', 147, 'En julio de 2025, los padrinos del heavy metal ofrecieron su último concierto en su querido Villa Park de Birmingham, reuniendo a generaciones de artistas a los que inspiraron para un homenaje irrepetible. Junto a la triunfal actuación final de Black Sabbath, la película cuenta con la participación de músicos influenciados por la banda, entre ellos Metallica, Guns N’ Roses, Slayer, Tool, Pantera, Yungblud y Papa (Ghost). Una despedida hístórica y emotiva a Ozzy y a la banda que cambió la música para siempre.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/OzzyBlackSabbathBackToTheBeginning/Es/720x1022_25.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/OzzyBlackSabbathBackToTheBeginning/Es/1440x990_7.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/OzzyBlackSabbathBackToTheBeginning/Es/6ab5d2d002934-back-beginning.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033794', 'El Gato Con Sombrero', 'el-gato-con-sombrero', 'A', 'COMEDIA, ANIMACIÓN', 114, '"¡Conoce a El Gato Con Sombrero como nunca antes lo habías visto! Fiel a la maravillosa y extravagante tradición de Dr. Seuss, El Gato Con Sombrero llega por primera vez a la pantalla grande en su debut cinematográfico animado, con una nueva y épica aventura cargada de irreverencia, donde reinan el caos, la magia y las travesuras. Haciendo lo que mejor sabe hacer, el Gato —con la voz de Bill Hader en su versión original— llena de alegría a los niños con su característico y singular sentido del humor, llevándolos a ellos y al público a un viaje fantástico por un mundo que jamás imaginaron. En la película, nuestro héroe se enfrenta a su misión más difícil hasta ahora para el I.I.I.I. (Instituto para la Institución de la Imaginación e Inspiración, S.A.): animar a Gabby y Sebastián, dos hermanos que están teniendo dificultades para adaptarse a su nueva ciudad. Conocido por siempre llevar las cosas al extremo, esta podría ser la última oportunidad de este agente del caos para demostrar su valía... o perder su sombrero mágico."', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElGatoConSombrero/Es/P_720X1022_5.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElGatoConSombrero/Es/Header_movie_details_B_1440X900_3.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElGatoConSombrero/Es/6adbac5a8e133-el-gato-con-sombrero.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033623', 'Godzilla Minus Zero', 'godzilla-minus-zero', 'B', 'CIENCIA FICCIÓN', 135, 'GODZILLA MINUS ZERO retoma la historia en 1949, dos años después de los turbulentos acontecimientos de Godzilla Minus One, y continúa la historia de la familia Shikishima mientras enfrentan una nueva catástrofe. Como proyecto filmado para IMAX, GODZILLA MINUS ZERO fue filmada con cámaras digitales de alta definición certificadas por IMAX y optimizada en sonido e imagen de manera única para pantallas IMAX. Los fans podrán ver a Godzilla llevado a nuevas y terroríficas alturas, haciendo de GODZILLA MINUS ZERO un verdadero evento cinematográfico imperdible.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/GodzillaMinusZero/Es/Poster_720x1022_Godzilla_5ago1_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/GodzillaMinusZero/Es/Header_movie_1440x900_Still_Godzilla_5ago_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/GodzillaMinusZero/Es/6a7ccff3283f2-godzilla-minus-zero.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033376', 'Street Fighter', 'street-fighter', 'B', 'DRAMA, ACCIÓN', 119, 'Ambientada en 1993, los distanciados luchadores callejeros Ryu (Andrew Koji) y Ken Masters (Noah Centineo) se ven obligados a volver al combate cuando la misteriosa Chun-Li (Callina Liang) los recluta para el próximo Torneo Mundial de Luchadores: un brutal enfrentamiento de puños, destino y furia. Pero detrás de esta batalla real se esconde una conspiración mortal que los obliga a enfrentarse entre sí y a los demonios de su pasado. Y si no lo hacen, ¡GAME OVER!', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/StreetFighter/Es/sf_desktop_poster_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/StreetFighter/Es/sf_desktop_header_movie_details_1440x900_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/StreetFighter/Es/6a870c70166c5-street-fighter.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033129', 'El Corazón De La Bestia', 'el-corazon-de-la-bestia', 'B', 'DRAMA, ACCIÓN', 101, 'Tras un aterrador accidente aéreo, el oficial de Fuerzas Especiales James Belmont (Brad Pitt) y su perro de combate, Odin, quedan varados en lo profundo de la naturaleza salvaje de Alaska. Juntos, se ven obligados a librar una brutal lucha por la supervivencia contra los elementos. Del aclamado cineasta David Ayer, Heart of the Beast es un intenso thriller de aventura que explora el vínculo irrompible entre un hombre y su mejor amigo mientras enfrentan su mayor batalla hasta ahora.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElCorazonDeLaBestia/Es/720x1022_24.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElCorazonDeLaBestia/Es/HOBT_A_1_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElCorazonDeLaBestia/Es/6a44173cccd16-HOTB_W8_1366x770_1.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033427', 'Ciudad De Muertos', 'ciudad-de-muertos', 'B15', 'THRILLER', 102, 'Inspirada en la obra de Enrique Metinides, Ciudad de Muertos sigue a Enrique, un fotógrafo de nota roja en la Ciudad de México de los años 50, cuya obsesión por documentar la tragedia comienza a desdibujar los límites entre la realidad y la imaginación. Tras un terremoto que deja la ciudad en ruinas, empieza a experimentar apariciones extrañas, visiones inquietantes y encuentros con un hombre desfigurado que parece seguirlo. En medio del caos, irrumpe Yola, una niña curiosa y enigmática que lo acompaña en un recorrido donde la frontera entre los vivos y los muertos se vuelve cada vez más difusa.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/CiudadDeMuertos/Es/720x1022_27.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/CiudadDeMuertos/Es/DESKTOP_Header_Movie_details_1440x900px__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/CiudadDeMuertos/Es/6abc4aa02b3b9-ciudad-muertos.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('lecciones-de-otono', 'Lecciones De Otoño', 'lecciones-de-otono', 'B', 'DRAMA', 85, 'En el otoño de su vida, don Alfonso Aldaz Iglesias (Miguel Pizarro) espera con ansias el final de sus días en su piso de Madrid. Sin embargo, quien llama a su puerta no es la muerte, sino un inesperado visitante que le ofrecerá un destino diferente al anhelado. Una película esperanzadora basada en la exitosa novela de Iván Eduardo Lópezcampos que nos invita a descubrir detalles de la vida que solemos pasar por alto y nos lleva a replantearnos cómo nos relacionamos con nuestros mayores. Una apuesta valiente por un cine con valores; una historia que nos inspira a ser más humanos.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LeccionesDeOtono/Es/19_Poster_720x1022_1.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LeccionesDeOtono/Es/14_Header_Movie_details_1440x90014_Header_Movie_details_1440x900_copia_2_.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LeccionesDeOtono/Es/6adba974999e4-lecciones-de-otono.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033073', 'El Poder De La Red', 'el-poder-de-la-red', 'B', 'DRAMA, THRILLER', 112, 'Como complemento de la exitosa película La red social, el guion original de Sorkin se basa en los hechos que dieron origen al impactante reportaje del Wall Street Journal, Los archivos de Facebook. La película se inspira en la historia real de cómo Frances Haugen (Madison), una joven ingeniera de Facebook, recluta a Jeff Horwitz (White), un reportero del Wall Street Journal, para emprender un peligroso viaje que termina por revelar los secretos mejor guardados de la red social.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElPoderDeLaRed/Es/720x1022_25.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElPoderDeLaRed/Es/TSR_1440x900_V1_copia_2_.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElPoderDeLaRed/Es/6aa16953e44ac-poder-red.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033358', 'Madre Siniestra', 'madre-siniestra', 'B', 'HORROR PSICOLÓGICO', 93, 'Bela, una niña de 8 años que vive en un hogar con problemas matrimoniales, se enfrenta a una entidad siniestra que sale de su clóset. La presencia, a quien ella llama "Otra Mamá", se vuelve cada vez más amenazante para ella y su familia.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/MadreSiniestra/Es/20_Po_ster_720x1022px__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/MadreSiniestra/Es/15_Header_Movie_details_1440x900px__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/MadreSiniestra/Es/6a8f6e14b4a58-madre-siniestra.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('verity-la-sombra-de-un-engano', 'Verity: La Sombra De Un Engaño', 'verity-la-sombra-de-un-engano', 'B15', 'SUSPENSO', 117, 'Basada en la exitosa novela de Colleen Hoover, este seductor thriller psicológico sigue a la reconocida autora Verity Crawford (Anne Hathaway) y a Lowen Ashleigh (Dakota Johnson), una escritora en apuros que se muda a la remota mansión Crawford para escribir como ghostwriter para Verity. Después de que Lowen descubre lo que parecen ser las escalofriantes notas autobiográficas de Verity, lucha con las perturbadoras y retorcidas confesiones sobre el esposo de Verity, Jeremy (Josh Hartnett), y le resulta difícil separar la ficción de la realidad, la manipulación de la atracción, y la oportunidad de la obsesión.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/VerityLaSombraDeUnEngano/Es/VRTY_2026_Desktop_Cinepolis_Poster_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/VerityLaSombraDeUnEngano/Es/VRTY_2026_Desktop_Cinepolis_HeaderMovieDetails_1440x900_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/VerityLaSombraDeUnEngano/Es/6a91ece8785e6-verity.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033682', 'Stray Kids World Tour <RUN IT> LIVE VIEWING', 'stray-kids-world-tour-run-it-live-viewing', 'A', 'CONCIERTO', 195, 'Por primera vez, Stray Kids presenta una transmisión especial en vivo de «Stray Kids World Tour » desde el Tokyo Dome en cines de todo el mundo. Fiel al título de la gira, refleja el impulso del grupo por adentrarse en mundos más grandes y subir a escenarios más audaces. Los ocho miembros (Bang Chan, Lee Know, Changbin, Hyunjin, HAN, Felix, Seungmin e I.N) desatan una energía imparable a través de coreografías explosivas y voces potentes, llevando la experiencia en vivo a su punto más álgido. Su presentación empieza con «Hall of Fame», una canción que expresa la ambición de Stray Kids de escribir su propia historia, trazando su crecimiento musical desde el principio hasta donde están ahora. La producción se enriquece aún más con montajes escénicos dinámicos, toques de espectáculos tradicionales coreanos y una iluminación láser espectacular, todo diseñado para que el público —tanto en el estadio como en el cine— se ponga de pie, cante, baile y celebre junto con los artistas. Grabado en vivo desde Tokio y transmitido a cines de todo el mundo, este evento de proyección en vivo te permite a ti, como parte de STAY, disfrutar de la magnitud, el espectáculo y la energía pura del show en vivo de Stray Kids —todos juntos, en la pantalla grande.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/StrayKidsWorldTourRUNITLIVEVIEWING/Es/StrayKids_LiveViewing_720x1022_copia.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/StrayKidsWorldTourRUNITLIVEVIEWING/Es/StrayKids_LiveViewing_1440x900_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/StrayKidsWorldTourRUNITLIVEVIEWING/Es/6ad112c94c215-Stray_Kids_World_Tour_30_Trailer_SPANISH_W8_1366x770.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033762', 'Rocky - 50 Aniversario ', 'rocky-50-aniversario', 'A', 'DRAMA', 119, 'Rocky nos lleva hasta los barrios marginales de Filadelfia. Allí, Rocky Balboa recauda las deudas impagadas para Tony Gazzo, un usurero, y combate de vez en cuando, tan solo por un puñado de dólares, en combates de boxeo con el apodo de "El Potro Italiano". Desgraciadamente su antiguo entrenador, Mickey, le deja tirado. Su amigo Paulie, que trabaja en un almacén de congelados, anima a Rocky a salir con su hermana Adrian, una joven tímida que trabaja como vendedora en una tienda de mascotas. Durante ese tiempo, Apollo Creed, el campeón del mundo de boxeo en la categoría de pesos pesados, buscará un nuevo contrincante para volver a disputarse el título y su elección será Rocky.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Rocky50Aniversario/Es/Rocky50Aniversario_720x1022_copia_2_.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Rocky50Aniversario/Es/Rocky50Aniversario_1440x900_copia_2_.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033766', 'The Babadook', 'el-babadoock', 'A', 'TERROR', 94, 'Amelia es una madre viuda que lucha por sacar adelante a su hijo Samuel, un niño tan inteligente como problemático. Cuando ambos descubren un inquietante libro infantil sobre una misteriosa criatura llamada El Babadook, una presencia oscura comienza a invadir su hogar y sus vidas. A medida que el miedo se apodera de ellos, Amelia deberá enfrentarse a una aterradora fuerza que parece alimentarse de sus peores pensamientos y emociones. Pero pronto descubrirá que algunos monstruos no habitan bajo la cama... sino en los rincones más profundos de nuestra mente.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/TheBabadook/Es/ElBabadook_poster_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/TheBabadook/Es/ElBabadook_1440x900.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033082', 'Duna: Parte Tres', 'duna-parte-3', 'A', 'DRAMA, THRILLER, ACCIÓN', 168, 'Warner Bros. Pictures y Legendary Pictures presentan «Dune: Parte Tres», que pone un final impresionante a la épica trilogía del cineasta Denis Villeneuve, nominado a los premios Óscar.«Dune: Parte Tres» se desarrolla casi dos décadas después de que Paul Atreides tomara el control del Imperio. Ahora, convertido en un emperador despiadado, Paul debe afrontar las consecuencias de su reinado mientras regresan antiguos aliados, surgen nuevas y aterradoras amenazas y la traición acecha en cada sombra.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/DunaParte3/Es/dune_3_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/DunaParte3/Es/dune_3_1440x900_copia.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
