INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00032798', 'Amarte', 'amarte', 'A', 'COMEDIA, ROMANCE', 96, 'Él vive en su propio universo. Ella es una famosa estrella de telenovelas que necesita desaparecer del suyo. Cuando se encuentran por accidente, lo que parece una mala idea se convierte en una escapada tan absurda como irresistible. Mientras huyen de la prensa, entre situaciones cada vez más fuera de lugar, momentos delirantes y una conexión que nadie vio venir, ambos descubren que escapar de la realidad puede ser mucho más divertido… y peligrosamente irresistible para el corazón. Pero cuando el mundo real vuelve a alcanzarlos, deberán decidir si ese encuentro fue sólo una fantasía perfecta o si vale la pena arriesgarse a vivir algo real.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Amarte/Es/amarte_poster_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Amarte/Es/amarte_header_movie_details_1440x900_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Amarte/Es/6a750336bcc28-amarte.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033634', 'La Caída De La Ballena', 'la-caida-de-la-ballena', 'B', 'SUSPENSO', 106, 'Tras la muerte de su padre (Josh Brolin), Jay Gardiner (Austin Abrams) se sumerge en la costa central de California en busca de sus restos, pero es tragado por un enorme cachalote. Atrapado en el interior del animal y con solo una hora de oxígeno restante, Jay descubre que las lecciones que su padre le enseñó podrían ser la clave para sobrevivir y escapar.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaCaidaDeLaBallena/Es/19_Poster_720x1022px__5.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaCaidaDeLaBallena/Es/4_Header_movie_details_1440x900px__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaCaidaDeLaBallena/Es/6abd9611801cc-whalefall.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033697', 'El Laberinto Del Fauno', 'el-laberinto-del-fauno', 'B15', 'DRAMA, FANTASÍA', 118, 'Con motivo de su 20.º aniversario, El laberinto del fauno, del visionario cineasta Guillermo del Toro, es una cinta de fantasía oscura ganadora del Premio de la Academia®, ambientada en la España de 1944. Mientras las fuerzas fascistas estrechan su control tras la Guerra Civil española, la joven Ofelia (Ivana Baquero) es llevada a un remoto puesto militar bajo el mando de su cruel padrastro (Sergi López). En medio de la brutalidad de la guerra, Ofelia descubre un laberinto oculto y se encuentra con un misterioso fauno que afirma que ella es una princesa perdida. Para recuperar su trono, deberá completar tres peligrosas pruebas que pondrán a prueba su valentía y su espíritu. A medida que la realidad y la fantasía se entrelazan, el viaje de Ofelia se convierte en una poderosa exploración de la inocencia, la resistencia y el poder perdurable de la imaginación frente a una oscuridad inimaginable.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElLaberintoDelFauno/Es/Poster_WEB_Desktop_720x1022px_43__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElLaberintoDelFauno/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_45__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElLaberintoDelFauno/Es/6ac6a503c38ac-el-laberinto-fauno.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('aniquilacion', 'Aniquilación', 'aniquilacion', 'C', 'THRILLER, ACCIÓN', 95, 'Cuando un escuadrón renegado de supersoldados genéticamente modificados escapa en el desierto, una francotiradora del Ejército, ruda y decidida, debe desatar el infierno para proteger a su pequeña hija.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Aniquilacion/Es/ANIQ_DESKTOP_P_ster_720x1022px_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Aniquilacion/Es/ANIQ_DESKTOP_Header_flujo_de_compra_1440x900px_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Aniquilacion/Es/6ac585128fb6d-aniquilacion.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('tierra-de-mi-padre', 'Tierra De Mi Padre', 'tierra-de-mi-padre', 'B', 'DRAMA', 82, 'En el apogeo de la Guerra Fría, Patria se centra en la relación entre el escritor Thomas Mann y su hija Erika —actriz, escritora y conductora de rally— mientras se embarcan en un viaje por carretera en un crucero Buick negro a través de una Alemania en ruinas.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/TierraDeMiPadre/Es/720x1022_24.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/TierraDeMiPadre/Es/1440x900_55.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/TierraDeMiPadre/Es/6a7cfbde56777-Fatherland.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033034', 'Resident Evil: Noche Cero', 'resident-evil-noche-cero', 'B15', 'TERROR, ACCIÓN', 94, 'De la mente del visionario cineasta Zach Cregger (Weapons, Barbarian) llega una emocionante —y aterradora— reinvención de la franquicia Resident Evil. En una historia completamente nueva, Resident Evil sigue a Bryan (Austin Abrams), un mensajero médico que, sin saberlo, se ve envuelto en una carrera por la supervivencia llena de acción y sin tregua cuando una noche fatídica y espantosa se convierte en un caos a su alrededor.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ResidentEvilNocheCero/Es/RE_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ResidentEvilNocheCero/Es/RE_1440x900_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ResidentEvilNocheCero/Es/6a7cfa8bd1eab-RESIDENTEVIL.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('digger', 'Digger', 'digger', 'B15', 'COMEDIA, DRAMA', 129, 'El cineasta ganador del Oscar Alejandro G. Iñárritu regresa con su película original DIGGER, protagonizada por Tom Cruise en el papel principal. El hombre más poderoso del mundo emprende una frenética misión para demostrar que es el salvador de la humanidad antes de que el desastre que ha desatado destruya todo.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Digger/Es/720x1022_28.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Digger/Es/HMD_1440X900_8.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Digger/Es/6a9883ec5b261-digger.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('hope-el-primer-impacto', 'Hope: El Primer Impacto ', 'hope-el-primer-impacto', 'B15', 'ACCIÓN', 157, 'Un misterioso descubrimiento se realiza en las afueras de la remota ciudad del puerto. Los residentes se encuentran en una lucha desesperada por la supervivencia contra algo que nunca antes habían encontrado.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/HopeElPrimerImpacto/Es/HOPE_Cinepolis_MX_DESKTOP_720_x_1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/HopeElPrimerImpacto/Es/HOPE_Cinepolis_MX_DESKTOP_1440_x_900_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/HopeElPrimerImpacto/Es/6aa87c469b3df-hope-el-primer-impacto.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('la-isla-de-las-munecas', 'La Isla De Las Muñecas', 'la-isla-de-las-munecas', 'B', 'TERROR', 80, 'Cuenta la leyenda de este lugar, que cerca de las chinampas de Don Julián una joven se ahogo entre los lirios y ahi su cuerpo fue encontrado.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaIslaDeLasMunecas/Es/IDLM_Poster_720X1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaIslaDeLasMunecas/Es/IDLM_Header_Movie_details_1440X900_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaIslaDeLasMunecas/Es/6ab437a2ae697-isla-munecas.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('super-canino', 'Súper Canino', 'super-canino', 'A', 'ANIMACIÓN, AVENTURA, FAMILIAR', 95, 'Danny es un niño tímido cuya vida cambia cuando su querido perro, Charlie, es abducido por extraterrestres y regresa con superpoderes, convertido en el famoso Súper Canino. Pero Puddy, un gato con poderes extraordinarios, está decidido a conquistar a la humanidad junto con su pandilla felina. Ahora, Danny y Charlie deberán superar sus diferencias y unir fuerzas para detener sus diabólicos planes.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/SuperCanino/Es/Poster_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/SuperCanino/Es/Header_movie_details_1440x900px__8.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/SuperCanino/Es/6abd5d97dcf3d-super-canino.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('tu-nombre', 'Tu Nombre', 'tu-nombre', 'A', 'ANIMACIÓN', 107, 'Mitsuha, una adolescente que vive en un pequeño pueblo de Japón, sueña con escapar de su vida cotidiana y conocer una ciudad llena de oportunidades. Taki, un joven que vive en Tokio, lleva una vida completamente diferente. Un día, ambos comienzan a intercambiar cuerpos misteriosamente mientras duermen, despertando cada uno en la vida del otro. Aunque al principio intentan comprender y controlar este extraño fenómeno, poco a poco desarrollan un vínculo especial a través de mensajes y recuerdos. Sin embargo, cuando el intercambio desaparece inesperadamente, Taki emprende una búsqueda para encontrar a Mitsuha y descubrir la verdad detrás de su conexión, enfrentándose a un misterio que trasciende el tiempo y el espacio. Revive esta historia 10 años despues de su estreno en salas de cine.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/TuNombre/Es/Poster_WEB_Desktop_720x1022px_35__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/TuNombre/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_35__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/TuNombre/Es/6ac6a52bbd523-your-name.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('cristiada', 'Cristiada', 'cristiada', 'B', 'DRAMA', 140, 'En el marco de los 100 años de la Guerra Cristera, hoy presentamos por primera vez en español la película Cristiada. Esta obra es mucho más que una crónica histórica de 1926 a 1929; nos cuenta la historia de un grupo apasionado de hombres y mujeres que deciden arriesgarlo todo por su familia, por el futuro de su país y, de manera fundamental, por defender su fe. Es, además, un poderoso relato sobre la transformación: seguimos los pasos de un líder inicialmente escéptico que, guiado por la convicción del joven José Sánchez del Río, termina al mando de todo el ejército cristero.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Cristiada/Es/Poster_WEB_Desktop_720x1022px_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Cristiada/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_5.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('el-arbol-magico', 'El Árbol Mágico', 'el-arbol-magico', 'A', 'FANTASÍA, FAMILIAR', 110, 'Una familia moderna debe mudarse al campo, sin wifi ni electricidad. Por lo tanto, los niños deben conectarse con la naturaleza que los rodea. Al explorar su nuevo hogar, descubren un árbol mágico con residentes extraordinarios y excéntricos. A través de las alegrías y los desafíos de cada una de sus aventuras, la familia aprende a reconectarse y a valorarse mutuamente por primera vez en años.​', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElArbolMagico/Es/720_copia_2_.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElArbolMagico/Es/Header_Movie_Details_1440x900_MFT_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/ElArbolMagico/Es/6aa32667e9b00-arbol-magico.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('coyote-vs-acme', 'Coyote Vs Acme', 'coyote-vs-acme', 'A', 'COMEDIA, AVENTURA, LIVE ACTION ', 103, 'Tras décadas de explosiones por productos defectuosos y cansado de caídas al abismo, Wile E. Coyote decide demandar a ACME. El coyote más emblemático junto con el universo de los Looney Toones, está decidido a desmantelar un imperio y enfrentar a su implacable CEO (John Cena). Esta batalla, destruirá a una leyenda... o a una corporación. La película que ACME NO QUIERE QUE VEAS.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/CoyoteVsAcme/Es/Poster_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/CoyoteVsAcme/Es/Header_movie_details_1440x900px__8.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/CoyoteVsAcme/Es/6a442a872bb67-CVA_Trailer_Zima_Dob_W8_1366x770.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('avengers-endgame-bonus', 'Avengers: Endgame Bonus', 'avengers-endgame-bonus', 'B', 'ACCIÓN, CIENCIA FICCIÓN', 191, 'Tras los devastadores sucesos de Avengers: Infinity War, el universo está en ruinas pero de los que quedan, los Avengers se unirán una vez más para deshacer la destrucción de Thanos y restaurar el orden del mundo.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/AvengersEndgameBonus/Es/19_Poster_720x1022px__5.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/AvengersEndgameBonus/Es/4_Header_movie_details_1440x900px__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/AvengersEndgameBonus/Es/6a95930ba5241-avengers-endgame-encore.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('hcf-seventeen-world-tour-new', 'HCF: SEVENTEEN WORLD TOUR NEW', 'hcf-seventeen-world-tour-new', 'A', 'CONCIERTO', 102, 'Para celebrar el décimo aniversario de su debut, SEVENTEEN se lanza a una gira mundial impulsados por su determinación de empezar de cero, tal como lo indica el título NEW_ Con su presencia escénica sin igual y su energía explosiva, SEVENTEEN vuelve a demostrar su potencial ilimitado. ¡Vive la intensidad del concierto —rebosante del encanto único de cada miembro— directamente en la pantalla grande!', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/HCFSEVENTEENWORLDTOURNEW/Es/Poster_WEB_Desktop_720x1022px_41__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/HCFSEVENTEENWORLDTOURNEW/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_42__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/HCFSEVENTEENWORLDTOURNEW/Es/6ac6a5d8f18ac-hybe-fest.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('hcf-tomorrow-x-together-world-tour-act', 'HCF: TOMORROW X TOGETHER WORLD TOUR ACT: TOMORROW', 'hcf-tomorrow-x-together-world-tour-act', 'A', 'CONCIERTO', 97, 'Como estrellas brillantes, la cuarta gira mundial de TOMORROW X TOGETHER, ACT: TOMORROW, se desarrolla como un viaje deslumbrante hacia el mañana que prometieron juntos. Desde su hermosa narrativa hasta la impresionante producción y las impactantes presentaciones en vivo que cautivaron a los MOA de todo el mundo, ¡vive la energía envolvente de la espectacular gira mundial de TOMORROW X TOGETHER en la pantalla grande!', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/HCFTOMORROWXTOGETHERWORLDTOURACTTOMORROW/Es/Poster_WEB_Desktop_720x1022px_40__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/HCFTOMORROWXTOGETHERWORLDTOURACTTOMORROW/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_40__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/HCFTOMORROWXTOGETHERWORLDTOURACTTOMORROW/Es/6ac6a5c1aa1bc-hybe-fest.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('hcf-enhypen-world-tour-blood-saga', 'HCF: ENHYPEN WORLD TOUR BLOOD SAGA ', 'hcf-enhypen-world-tour-blood-saga', 'A', 'CONCIERTO', 101, 'La gira mundial actual de ENHYPEN, BLOOD SAGA, sigue cautivando al público de todo el mundo. Revive el inolvidable concierto en Seúl que marcó el inicio de la BLOOD SAGA, donde cobra vida una fascinante fantasía oscura. La coreografía intensa y sincronizada de los integrantes y una escenografía espectacular e impresionante surgen de entre el resplandor rojo y la oscuridad profunda. ¡Disfruta del sonido intenso al estilo de una banda y del universo vampírico sin igual que solo ENHYPEN puede ofrecerte en los cines!', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/HCFENHYPENWORLDTOURBLOODSAGA/Es/Poster_WEB_Desktop_720x1022px_39__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/HCFENHYPENWORLDTOURBLOODSAGA/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_39__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/HCFENHYPENWORLDTOURBLOODSAGA/Es/6ac6a59c88ef8-hybe-fest.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033210', 'BTS WORLD TOUR ''ARIRANG'' IN SÃO PAULO: EN VIVO', 'bts-world-tour-arirang-in-sao-paulo', 'A', 'CONCIERTO', 195, 'BTS WORLD TOUR ''ARIRANG'' IN SÃO PAULO: LIVE VIEWING ¡Vive la experiencia BTS WORLD TOUR ''ARIRANG'' en cines de todo el mundo, transmitida desde São Paulo, Brasil! Como colofón de su gira por Latinoamérica, este concierto monumental llevará directamente a la pantalla grande toda la energía explosiva del estadio repleto de Brasil. Las transmisiones en algunos territorios están programadas en horario diferido para adaptarse a los husos horarios locales.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/BTSWORLDTOURARIRANGINSAOPAULO/Es/Poster_WEB_Desktop_720x1022px_37__6.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/BTSWORLDTOURARIRANGINSAOPAULO/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_37__6.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('palm-mi-chica-purpura', 'PALM Mi Chica Púrpura', 'palm-mi-chica-purpura', 'B', 'COMEDIA', 115, '1° PALMAR Film Festival. Mi Chica Púrpura. Mateo, un adolescente que vive sin atreverse a nada, conoce a Dara, una chica nueva e impredecible. Mientras su familia se desmorona y él y su mejor amigo planean vengarse del bully de la escuela, Mateo descubre que crecer duele y que ser diferente puede ser el mejor color.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/PALMMiChicaPurpura/Es/mi_chico_copia_1.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/PALMMiChicaPurpura/Es/_1440X900.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('palm-el-guardian', 'PALM El Guardián', 'palm-el-guardian', 'B', 'DRAMA', 116, '1° PALMAR Film Festival. El Guardián. Basilio es contratado para cuidar una playa desierta en Baja California. En este paraíso, en el que parece que no pasa nada, ocurren muchas cosas y algunas de ellas ilegales. Basilio, que es un hombre de normas morales férreas, busca hacer lo correcto. Sin embargo, lo que él cree que es hacer lo correcto le puede jugar en contra en una comunidad que apenas conoce.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/PALMElGuardian/Es/guardian_copia_2__1.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/PALMElGuardian/Es/_1440X900.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('palm-volar-y-otros-deseos', 'PALM Volar y Otros Deseos', 'palm-volar-y-otros-deseos', 'B', 'DRAMA', 103, '1° PALMAR Film Festival. Volar y Otros Deseos. Silvia es una mujer en sus sesentas inmersa en su rutina como madre de una familia tradicional, hasta que llega Varenka, quien hará que se cuestione su vida y su sexualidad.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/PALMVolaryOtrosDeseos/Es/volar_copia.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/PALMVolaryOtrosDeseos/Es/_1440X900_copia.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('fmorb-ferine', 'FMORB Ferine', 'fmorb-ferine', 'C', 'TERROR', 106, '19° Mórbido Film Fest. Ferine. Tras una devastadora tragedia personal, una acaudalada coleccionista de arte abandona su vida refinada para formar una familia poco convencional. Lo que comienza como una huida se convierte en un viaje destructivo de regresión primitiva y metamorfosis animal, donde el duelo y el hambre depredadora consumen lo que queda de su humanidad.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBFerine/Es/Ferine_copia_2__1.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBFerine/Es/1440x900_copia_13.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('fmorb-bloque-de-cortometrajes', 'FMORB Cinema Recomposed - Silent Monsters and more!', 'fmorb-bloque-de-cortometrajes', 'C', 'ANIMACIÓN', 112, '19° Mórbido Film Festival. Bloque de Cortometrajes. Bloque de cortometrajes seleccionados por Mórbido Fest 2026 que reúnen lo más reciente del cine fantástico y de horror hecho por nuevas voces de México, América Latina y el mundo. Monstruos, fantasmas, cuerpos que mutan y pesadillas muy cercanas a lo cotidiano: el formato corto como laboratorio donde el género se reinventa sin pedir permiso.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBCinemaRecomposedSilentMonstersandmore/Es/cinema_recomposed_copia.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBCinemaRecomposedSilentMonstersandmore/Es/1440x900_copia_13.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('fmorb-mi-amigo-el-sol', 'FMORB Mi Amigo el Sol', 'fmorb-mi-amigo-el-sol', 'A', 'ANIMACIÓN', 97, '19° Mórbido Film Fest. Mi Amigo el Sol. Diego y su hija Xóchitl venden pinturas de mitología mexicana en la Ciudad de México. Cuando el mural de Xóchitl da vida a una criatura mítica, es llevada al mundo de los dioses antiguos. Diego debe navegar por los mitos para salvarla.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBMiAmigoelSol/Es/Mi_Amigo_el_Sol_720x1022.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBMiAmigoelSol/Es/1440x900_68.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('fmorb-roto', 'FMORB Roto (Work in Progress)', 'fmorb-roto', 'C', 'TERROR', 105, '19° Mórbido Film Fest. Roto. Un año después de que un devastador accidente destrozara su vida, Ana Vega se ha aislado de todos y sobrevive por rutina más que por propósito. Una mañana es secuestrada y encerrada en un sótano por un misterioso captor. Ahí conoce a Otto, un hombre físicamente imponente, atrapado emocionalmente entre la niñez y la adultez. Con los días, el instinto de supervivencia de Ana choca con su creciente empatía por él, y juntos empiezan a desafiar las reglas de su encierro. Pero mientras una amenaza invisible se acerca, Ana deberá enfrentar sus propias heridas y descubrir si escapar del sótano será suficiente para ser libre.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBRoto/Es/roto_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBRoto/Es/1440x900_copia_13.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('fmorb-infirmary', 'FMORB Infirmary', 'fmorb-infirmary', 'C', 'TERROR', 102, '19° Mórbido Film Fest. Infirmary. Material recuperado de una cámara corporal revela la primera noche de un joven guardia de seguridad dentro de un hospital abandonado, donde una serie de incidentes perturbadores e inexplicables y un siniestro intruso hacen que su turno se salga de control.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBInfirmary/Es/Infirmary_720x1022.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBInfirmary/Es/1440x900_copia_2__13.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('fmorb-quince', 'FMORB Quince', 'fmorb-quince', 'C', 'TERROR', 87, '19° Mórbido Film Festival. Quince. Dos mejores amigas planean la mejor fiesta de quince años. Cuando una de ellas queda embarazada de una criatura monstruosa, el embarazo la convierte en un inesperado ícono social de la escuela, la amistad se fractura y la celebración soñada se vuelve peligrosamente surreal.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBQuince/Es/Delivery_70x100_Fest_Quince_27Mar_copia_2__1.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBQuince/Es/1440x900_copia_13.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('fmorb-victorian-psycho', 'FMORB Victorian Psycho', 'fmorb-victorian-psycho', 'C', 'TERROR, THRILLER', 90, '19° Mórbido Film Festival. Victorian Psycho. Inglaterra, 1858. Winifred Notty, una institutriz poco convencional, llega a Ensor House, una remota mansión gótica. Poco después de su llegada, miembros del servicio comienzan a desaparecer misteriosamente y los dueños de la casa empiezan a sospechar que hay algo siniestro en su nueva empleada.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBVictorianPsycho/Es/La_Psicopata_720x1022.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBVictorianPsycho/Es/1440x900_copia_2__13.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('fmorb-i-love-paris', 'FMORB I Love Paris', 'fmorb-i-love-paris', 'C', 'COMEDIA, TERROR', 120, '19° Mórbido Film Fest. I Love Paris. Después de ser mordida por una vampira, una joven cantante parisina persigue el estrellato a costa de su alma, en un falso documental donde la fama y la sed de sangre resultan perfectamente compatibles.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBILoveParis/Es/I_Love_Paris_720x1022_copia.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBILoveParis/Es/1440x900_copia_13.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('fmorb-gummy', 'FMORB Gummy', 'fmorb-gummy', 'C', 'COMEDIA, FANTASÍA', 82, '19° Mórbido Film Fest. Gummy. Mauro es un asesino en serie que sale una noche más en busca de una víctima. En un bar de carretera se cruza con Amaranta, una joven que, a primera vista, parece una presa fácil e indefensa.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBGummy/Es/Gummy_Poster_copia_2__1.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBGummy/Es/1440x900_68.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('fmorb-the-ones-who-grieve', 'FMORB The Ones Who Grieve', 'fmorb-the-ones-who-grieve', 'C', 'TERROR', 116, '19° Mórbido Film Fest. The Ones Who Grieve. A finales del siglo XIX, en una granja aislada, Zélie vive sometida a la autoridad de su padre, Jacob, un hombre profundamente religioso. Mientras una misteriosa enfermedad conocida como el ''Velo Negro'' arrasa la campiña y la fe empieza a confundirse con la locura, ella deberá luchar por preservar su humanidad y conquistar su libertad.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBTheOnesWhoGrieve/Es/The_Ones_Who_Grieve_720x1022_copia.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBTheOnesWhoGrieve/Es/1440x900_68.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('fmorb-el-fantasma-en-la-celda', 'FMORB El Fantasma en la Celda', 'fmorb-el-fantasma-en-la-celda', 'C', 'TERROR', 106, '19° Mórbido Film Fest. El Fantasma en la Celda. En una de las prisiones más brutales de Indonesia, una fuerza invisible comienza a asesinar reclusos de forma atroz. Pandillas enemigas y guardias corruptos se ven obligados a colaborar para sobrevivir al creciente baño de sangre.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBElFantasmaenlaCelda/Es/Ghost_in_the_Cell_Poster_copia_1.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBElFantasmaenlaCelda/Es/1440x900_copia_2__13.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('fmorb-ken-russells-the-devils', 'FMORB Ken Russell''s The Devils', 'fmorb-ken-russells-the-devils', 'C', 'TERROR', 114, '19° Mórbido Film Fest. Ken Russell''s The Devils. Francia, 1634. Urbain Grandier, un carismático y libertino sacerdote de Loudun, se convierte en el blanco de una conspiración política y religiosa cuando una monja reprimida, obsesionada con él, lo acusa de brujería tras una ola de supuestas posesiones demoníacas en el convento. Un juicio fanático lo condena a la hoguera.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBKenRussellsTheDevils/Es/The_Devils_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBKenRussellsTheDevils/Es/1440x900_copia_13.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('fmorb-our-effed-up-world', 'FMORB Our Effed Up World', 'fmorb-our-effed-up-world', 'C', 'TERROR, CIENCIA FICCIÓN', 68, '19° Mórbido Film Fest. Our Effed Up World. La historia sigue a Sheri, una joven que intenta superar el reciente fallecimiento de su abuela lidiando con la apatía y refugiándose en su grupo de amigos cinéfilos. Sin embargo, cuando un misterioso meteorito verde se estrella en los bosques cercanos y comienzan misteriosas desapariciones, el grupo descubre una entidad extraterrestre con un hambre insaciable que amenaza al mundo, conectada además con el pasado del padre de Sheri.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBOurEffedUpWorld/Es/Our_Effed_Up_World_720x1022_copia_2_.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBOurEffedUpWorld/Es/1440x900_copia_13.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('fmorb-upiro', 'FMORB Upiro', 'fmorb-upiro', 'C', 'TERROR', 106, '19° Mórbido Film Festival. Upiro. Año 1755. Una joven es enviada a un monasterio de clausura en el que varias novicias sufren una extraña enfermedad de la sangre. Un franciscano poco convencional investiga estos inquietantes sucesos, pero sus métodos chocarán con el pensamiento científico imperante en el Siglo de las Luces.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBUpiro/Es/Upiro_720x1022_copia.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBUpiro/Es/1440x900_68.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('fmorb-the-remedy', 'FMORB The Remedy', 'fmorb-the-remedy', 'C', 'TERROR, THRILLER', 90, '19° Mórbido Film Fest. The Remedy. Un joven atormentado cuida de su madre, enferma terminal, y de su hermana, que padece una enfermedad mental. En un intento desesperado por mantener viva a su madre, recurre a un remedio poco convencional que la lleva a ansiar carne viva y desata una entidad sobrenatural que se alimenta de carne humana.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBTheRemedy/Es/The_Remedy_720x1022_copia.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBTheRemedy/Es/1440x900_copia_2__13.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('fmorb-sender', 'FMORB Sender', 'fmorb-sender', 'C', 'THRILLER', 94, '19° Mórbido Film Fest. Sender. Una mujer comienza a recibir paquetes misteriosos con objetos inquietantemente personales. Decidida a descubrir quién se los envía, se embarca en una investigación paranoica que la arrastra a cuestionar su propia identidad.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBSender/Es/Sender_720x1022_copia_2_.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBSender/Es/1440x900_copia_13.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('fmorb-bloody-tennis', 'FMORB Bloody Tennis', 'fmorb-bloody-tennis', 'C', 'TERROR', 90, '19° Mórbido Film Fest. Bloody Tennis. Sophie, una prometedora tenista estadounidense, ingresa a una academia de élite escondida en el sur de Europa. Ahí descubre que la directora, el personal y el régimen de entrenamiento esconden intenciones siniestras, mientras la feroz competencia se tiñe de sangre.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBBloodyTennis/Es/Bloody_Tennis_copia_2__1.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBBloodyTennis/Es/1440x900_67.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('fmorb-sicko', 'FMORB Sicko', 'fmorb-sicko', 'C', 'COMEDIA, THRILLER', 102, '19° Mórbido Film Fest. Sicko. En Almaty, una pareja ahogada en deudas finge una enfermedad terminal y lanza una campaña de crowdfunding para salir adelante. Su éxito viral llama la atención de criminales y el plan se sale peligrosamente de control, desembocando en violencia y caos: un retrato feroz de la precariedad económica contemporánea.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBSicko/Es/Sicko_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBSicko/Es/1440x900_67.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('fmorb-bowels-of-hell', 'FMORB Bowels of Hell', 'fmorb-bowels-of-hell', 'C', 'COMEDIA, TERROR', 111, '19° Mórbido Film Fest. Bowels of Hell. Malu organiza una fiesta de revelación de género mientras carga con el duelo, problemas digestivos y un hijo adolescente trans que reprueba su trabajo. Cuando los inodoros de su condominio se transforman en criaturas asesinas por una misteriosa maldición, entra en una pesadilla surreal donde la maternidad, el duelo y el terror existencial no se pueden simplemente jalar por el escusado.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBBowelsofHell/Es/Bowels_of_Hell_Poster_copia_2__1.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBBowelsofHell/Es/1440x900_copia_2__13.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('fmorb-el-infinito', 'FMORB El Infinito (Work in Progress)', 'fmorb-el-infinito', 'C', 'TERROR, THRILLER', 82, '19° Mórbido Film Fest. El Infinito. Anaís, una mujer atormentada por el duelo tras la muerte de su padre, entra en una espiral autodestructiva. Su hermana mayor la interna en un retiro espiritual que promete atención médica especial y una transformación profunda, sin saber que la está entregando a una peligrosa secta.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBElInfinito/Es/El_Infinito_Poster_1.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FMORBElInfinito/Es/1440x900_copia_13.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('vertigo-2-punto-muerto', 'Vértigo 2: Punto Muerto', 'vertigo-2-punto-muerto', 'B', 'SUSPENSO', 98, 'Durante una peligrosa escalada en el monte Kwan, en Tailandia, dos escaladoras quedan atrapadas a miles de metros sobre el suelo, donde las alturas vertiginosas, la exposición extrema y las pocas probabilidades de sobrevivir convierten cada instante en una lucha por mantenerse con vida.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Vertigo2PuntoMuerto/Es/Poster_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Vertigo2PuntoMuerto/Es/Header_movie_details_1440x900px__8.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/Vertigo2PuntoMuerto/Es/6a98833208c7b-vertigo-2.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00033701', 'Fiesta Pagana', 'fiesta-pagana', 'A', 'BIOPIC', 128, 'A finales de los años ochenta, un grupo de jóvenes de barrio decide desafiar todas las reglas y perseguir un sueño que parecía imposible: fusionar la fuerza del heavy metal con la magia del folk celta. Lo que comenzó como la aventura de unos amigos acabó convirtiéndose en un fenómeno que revolucionó el rock en español y cambió sus vidas para siempre. FIESTA PAGÄNA es una película de ficción inspirada en la extraordinaria historia de Mägo de Oz. Comedia, musical, drama y ópera rock, explora lo que sucede cuando los sueños se cumplen y el éxito empieza a cobrar su precio. Sus canciones se convirtieron en la banda sonora de varias generaciones y en himnos que todavía hoy cantan millones de personas a ambos lados del Atlántico. Porque más de tres décadas después, la música y la leyenda de Mägo de Oz siguen más vivas que nunca. Inspirada en hechos reales. En cuáles depende de a qué miembro de la banda se le pregunte.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FiestaPagana/Es/FiestaPagana_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/FiestaPagana/Es/FiestaPagana_1440x900_2.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('tadeo-el-explorador-y-la-lampara-maravillosa', 'Tadeo El Explorador Y La Lámpara Maravillosa', 'tadeo-el-explorador-y-la-lampara-maravillosa', 'AA', 'ANIMACIÓN, FAMILIAR', 94, 'Tadeo y Sara son ahora padres de Olimpia (Oli), una adorable e intrépida niña de dos años. Y Momia no lleva nada bien haber dejado de ser el centro de atención. Mientras están de vacaciones en Londres, Sara sigue la pista de un objeto único: la lámpara maravillosa de Las mil y una noches. Y Momia, lleno de celos, pide un deseo: viajar en el tiempo hasta el momento en que era joven y todos le querían. Tadeo y Sara tienen que unir fuerzas para evitar que Momia cambie el curso de la historia y traer al grupo (Jeff, Belzoni y Ramona incluidos) de vuelta a casa. Esta nueva aventura los llevará a cruzar el Océano Atlántico desde la mítica ciudad perdida de Paititi hasta Grecia, y de allí a lo más profundo de Oriente Medio, hasta la misma cueva de Ali Babá y los Cuarenta ladrones.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/TadeoElExploradorYLaLamparaMaravillosa/Es/tj4_de_1_6_720x1022_1.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/TadeoElExploradorYLaLamparaMaravillosa/Es/tj4_de_1_2_1440x900_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/TadeoElExploradorYLaLamparaMaravillosa/Es/6a4d6b1d28bec-tadeo-lampara-maravillosa.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('mary-y-max', 'Mary Y Max', 'mary-y-max', 'B', 'DRAMA', 92, 'Una historia de amistad entre dos personas totalmente distintas: Mary una pequeña y solitaria niña de ocho años, que vive en los suburbios de Melbourne, Australia, y Max, un hombre de cuarenta y cuatro años, también solitario, que vive en Nueva York, Estados Unidos. La primera película de Adam Elliot, ganador del Oscar y director de ''Memorias de un Caracol'', llega por primera vez a los cines de México.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/MaryYMax/Es/P_ster_720x1022px_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/MaryYMax/Es/Header_Movie_details_1440x900px_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/MaryYMax/Es/6a7cf92d3af60-maryandmax.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('la-isla-olvidada', 'La Isla Olvidada', 'la-isla-olvidada', 'A', 'COMEDIA, ANIMACIÓN, AVENTURA', 109, 'Dos mejores amigos se quedan varados en el místico mundo de Nakali, donde su único escape podría costarles su vida compartida de recuerdos.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaIslaOlvidada/Es/20_P_ster_720x1022px__5.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaIslaOlvidada/Es/5_Header_movie_details_1440x900px_1__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaIslaOlvidada/Es/6a1f26892eb3d-la-isla-olvidada.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('gungo-y-los-juegos-cavernicolas', 'Gungo Y Los Juegos Cavernícolas', 'gungo-y-los-juegos-cavernicolas', 'A', 'COMEDIA, FAMILIAR', 96, 'Gungo es considerado el cavernícola más débil de la tribu, pero como es el hijo del Jefe, cree que tiene el futuro asegurado y que no debe demostrar su valía de ninguna manera. Sin embargo, es traicionado por un grupo de rebeldes que quieren usurpar el poder y es expulsado a tierras inhóspitas donde no hay nada. Para sobrevivir y desenmascarar el complot en su contra, deberá encontrar su verdadera fortaleza interna, liderar a un grupo de inadaptados y competir en los brutales Juegos Cavernícolas, reservados para los más fuertes. Porque cuando tocas fondo… ¡solo queda picar piedra para subir poco a poco!', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/GungoYLosJuegosCavernicolas/Es/GUNGO_Poster_720x1022_DESKTOP_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/GungoYLosJuegosCavernicolas/Es/GUNGO_Headermoviedetails_1400x900_DESKTOP_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/GungoYLosJuegosCavernicolas/Es/6a32d30d14212-gungo-y-los-juegos-cavernicolas.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('la-odisea', 'La Odisea', 'la-odisea', 'B', 'ACCIÓN, ÉPICA', 172, 'El legendario Odiseo enfrenta peligros épicos en su viaje de regreso a casa tras la Guerra de Troya. Se topa con criaturas míticas y dioses caprichosos, superando obstáculos increíbles antes de reunirse con su amada Penélope.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaOdisea/Es/9_P_ster_720x1022px__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaOdisea/Es/5_Header_movie_details_1440x900px__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LaOdisea/Es/6a0df392ebc25-la-odisea.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('las-catadoras-de-hitler', 'Las Catadoras De Hitler', 'las-catadoras-de-hitler', 'B15', 'DRAMA', 123, 'Otoño de 1943. Huyendo de los bombardeos, Rosa se refugia en un pueblo cercano a la Guarida del Lobo, sin saber que será reclutada como catadora de Hitler. Obligada a probar comida que podría matarla, encuentra miedo, alianzas inesperadas y un deseo prohibido que pondrá a prueba su corazón. Basada en el bestseller ''La catadora'' de Rosella Postorino.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LasCatadorasDeHitler/Es/Las_catadoras_de_Hitler_Poster_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LasCatadorasDeHitler/Es/Header_Movie_details_1440x900_5.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/LasCatadorasDeHitler/Es/6a57c6c6de7cb-las-catadoras.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('caballo-salvaje-nueve', 'Caballo Salvaje Nueve', 'caballo-salvaje-nueve', 'A', 'DRAMA, THRILLER, CRIMEN', 118, 'Poco antes del golpe de Estado chileno de 1973, los agentes de la CIA Chris (John Malkovich) y Lee (Sam Rockwell) son enviados desde Santiago a la Isla de Pascua por su jefe, MJ (Steve Buscemi). Entre las icónicas estatuas de la isla, y mientras los socios de larga data lidian con sus pasados oscuros y conspiraciones presentes, el nuevo vínculo de Chris con unas estudiantes rebeldes (Mariana di Girolamo y Ailín Salas) pone en riesgo el curso del viaje en este paraíso remoto.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/CaballoSalvajeNueve/Es/19_Poster_720x1022px__5.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/CaballoSalvajeNueve/Es/14_Header_Movie_details_1440x900px__2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/CaballoSalvajeNueve/Es/6ac67c0b5a1c5-caballo-salvaje-nueve.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('ceniza-en-la-boca', 'Ceniza En La Boca', 'ceniza-en-la-boca', 'B15', 'DRAMA', 102, 'En busca de una vida mejor, Lucila viaja con su hermano Diego desde México para encontrarse con su madre en Madrid, quien lleva ahí ocho años trabajando ilegalmente para mantenerlos. Al llegar, la vida que los espera resulta más dura de lo que imaginaban.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/CenizaEnLaBoca/Es/CEB_Poster_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/CenizaEnLaBoca/Es/CEB_Header_movie_details1440x900_copia.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/CenizaEnLaBoca/Es/6acff3c21954e-ceniza-boca.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('grin-el-juego-de-la-ouija', 'Grin: El Juego De La Ouija', 'grin-el-juego-de-la-ouija', 'B15', 'DRAMA, TERROR, FANTASÍA', 81, 'Eve regresa a casa para reunirse con su familia, después de varios años de no verse. La reunión familiar también significa conocer a Lucien, la nueva pareja de su madre, un hombre que lleva consigo un extraño juego de mesa muy antiguo. Lo que comienza como una actividad para pasar el tiempo pronto se convierte en una pesadilla cuando el juego libera a GRIN, una entidad demoníaca con apariencia de bufón que comienza a perseguir a quienes esconden terribles secretos del pasado. GRIN no parece matar al azar. Ha venido a castigar.', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/GrinElJuegoDeLaOuija/Es/GRIN_poster_720X1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/GrinElJuegoDeLaOuija/Es/GRIN_header_movie_details_1440x900_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/GrinElJuegoDeLaOuija/Es/6ac7beb69c549-grin-juego-ouija.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('klara-y-el-sol', 'Klara Y El Sol', 'klara-y-el-sol', 'A', 'COMEDIA, DRAMA', 116, 'Basada en la exitosa novela del premio Nobel Kazuo Ishiguro y escrita y dirigida por el ganador del premio Óscar® Taika Waititi (Jojo Rabbit), Klara y el Sol presenta al público a Klara (Jenna Ortega), una Amiga Artificial que solo desea encontrar el hogar perfecto. Cuando Klara conoce a Josie (Mia Tharia), ambas sienten de inmediato una conexión especial. Josie tiene una relación tensa con su madre (Amy Adams) y han sufrido grandes pérdidas, pero la inocencia y la lealtad inquebrantable de Klara comienzan a sanar a la familia e iluminar el complejo mundo de Josie', 'Cartelera', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/KlaraYElSol/Es/SMBND_720x1022_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/KlaraYElSol/Es/KATS_1440x900_2.jpg', 'https://pimcore-content.cinepolis.com/assets/Mexico/Tickets/Movies/KlaraYElSol/Es/6aa879abaa225-klara-y-el-sol.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = CASE     WHEN EXCLUDED.sinopsis IS NOT NULL AND EXCLUDED.sinopsis != '' AND EXCLUDED.sinopsis != 'Sin sinopsis disponible' AND LENGTH(EXCLUDED.sinopsis) > 5     THEN EXCLUDED.sinopsis     ELSE PELICULA.sinopsis END, poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
